SELECT percentile_cont(0.25) within GROUP (ORDER BY icustays.los) AS percentile_25 FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) = 55 AND admissions.admission_type_id = 171 AND icustays.los IS NOT NULL AND EXTRACT(YEAR FROM icustays.intime) BETWEEN 2010 AND 2015;